/**
 * One PostToolUse process per tool call (yellow-refactor M1, phase 2).
 *
 * Live on CC 2.1.316 (src/hooks/docs/hook-process-measurements/
 * 2026-10-31-main-live.json) an Edit starts 14 ork PostToolUse processes and
 * a Bash 8. posttool/tool-dispatcher runs the same handlers in one process,
 * routed by the same group matchers, and merges their results. It is wired
 * only into the flag variant (scripts/unified-pretool-hooks.mjs); the shipped
 * hooks.json is unchanged.
 */

import { describe, it, expect, vi } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { HookInput, HookResult } from '../../types.js';
import {
  posttoolDispatch,
  POSTTOOL_GROUPS,
  POSTTOOL_HANDLERS,
  ccMatcherMatches,
} from '../../posttool/tool-dispatcher.js';
import {
  unifiedToolHooks,
  UNIFIED_POSTTOOL_HANDLER,
} from '../../../scripts/unified-pretool-hooks.mjs';
import { createTestContext } from '../fixtures/test-context.js';

const HOOKS_JSON = join(__dirname, '..', '..', '..', 'hooks.json');
const shipped = JSON.parse(readFileSync(HOOKS_JSON, 'utf8'));
const SILENT: HookResult = { continue: true, suppressOutput: true };

function input(tool_name: string): HookInput {
  return {
    hook_event_name: 'PostToolUse',
    tool_name,
    tool_input: {},
    tool_response: {},
    session_id: 'test-session',
    project_dir: '/tmp/project',
  } as unknown as HookInput;
}

/** A handler map where every id is a spy returning `result(id)`. */
function fakes(result: (id: string) => HookResult = () => SILENT) {
  const calls: string[] = [];
  const map: Record<string, (i: HookInput) => HookResult> = {};
  for (const id of Object.keys(POSTTOOL_HANDLERS)) {
    map[id] = vi.fn(() => {
      calls.push(id);
      return result(id);
    });
  }
  return { map, calls };
}

describe('posttool/tool-dispatcher route table', () => {
  it('mirrors the shipped PostToolUse groups exactly (matcher, id, async, order)', () => {
    const fromJson = shipped.hooks.PostToolUse.map((g: { matcher?: string; hooks: { args: string[]; async?: boolean }[] }) => ({
      matcher: g.matcher ?? '*',
      hooks: g.hooks.map((h) => ({ id: h.args[1], async: Boolean(h.async) })),
    }));
    expect(POSTTOOL_GROUPS).toEqual(fromJson);
  });

  it('has a handler for every id it routes to', () => {
    for (const g of POSTTOOL_GROUPS) for (const h of g.hooks) expect(POSTTOOL_HANDLERS, h.id).toHaveProperty([h.id]);
  });

  it('matches like CC: identifiers exact, anything else an unanchored regex', () => {
    expect(ccMatcherMatches('Write|Edit', 'Edit')).toBe(true);
    expect(ccMatcherMatches('Write|Edit', 'NotebookEdit')).toBe(false);
    expect(ccMatcherMatches('mcp__*', 'mcp__context7__query-docs')).toBe(true);
    expect(ccMatcherMatches(undefined, 'Anything')).toBe(true);
  });
});

describe('posttool/tool-dispatcher routing', () => {
  it.each([
    ['Edit', 14],
    ['Bash', 8],
    ['Read', 2],
  ])('runs the same %s handlers the shipped file launches (%i)', async (tool, n) => {
    const { map, calls } = fakes();
    await posttoolDispatch(input(tool), createTestContext(), map);
    expect(calls).toHaveLength(n);
    expect(new Set(calls).size).toBe(n);
  });

  it('runs an identical id once even when two matching groups list it (CC dedupes)', async () => {
    const { map, calls } = fakes();
    const groups = [
      { matcher: 'Edit', hooks: [{ id: 'posttool/commit-nudge', async: true }] },
      { matcher: '*', hooks: [{ id: 'posttool/commit-nudge', async: true }] },
    ];
    await posttoolDispatch(input('Edit'), createTestContext(), map, groups);
    expect(calls).toEqual(['posttool/commit-nudge']);
  });

  it('a tool no group matches runs nothing', async () => {
    const { map, calls } = fakes();
    const r = await posttoolDispatch(input('TodoWrite'), createTestContext(), map);
    expect(calls).toHaveLength(0);
    expect(r.continue).toBe(true);
  });
});

describe('posttool/tool-dispatcher merge', () => {
  const ctxOut = (text: string): HookResult => ({
    continue: true,
    hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: text },
  });

  it('merges additionalContext from sync and async handlers', async () => {
    const { map } = fakes((id) =>
      id === 'posttool/auto-lint' ? ctxOut('lint says') : id === 'posttool/commit-nudge' ? ctxOut('commit soon') : SILENT,
    );
    const r = await posttoolDispatch(input('Edit'), createTestContext(), map);
    const text = r.hookSpecificOutput?.additionalContext ?? '';
    expect(text).toContain('lint says');
    expect(text).toContain('commit soon');
  });

  it('a sync block wins; an async handler cannot block', async () => {
    const block: HookResult = { continue: true, decision: 'block', reason: 'drift' };
    const { map } = fakes((id) => (id === 'posttool/check-plugins-drift' ? block : id === 'posttool/ascii-lint' ? { continue: false, stopReason: 'x' } : SILENT));
    const r = await posttoolDispatch(input('Edit'), createTestContext(), map);
    expect(r.decision).toBe('block');
    expect(r.reason).toContain('drift');
    expect(r.continue).toBe(true);
  });

  it('keeps a sync updatedToolOutput and ignores one from an async handler', async () => {
    const { map } = fakes((id) =>
      id === 'posttool/secret-handler'
        ? { continue: true, hookSpecificOutput: { hookEventName: 'PostToolUse', updatedToolOutput: 'redacted' } }
        : id === 'skill/redact-secrets'
          ? { continue: true, hookSpecificOutput: { hookEventName: 'PostToolUse', updatedToolOutput: 'late' } }
          : SILENT,
    );
    const r = await posttoolDispatch(input('Bash'), createTestContext(), map);
    expect(r.hookSpecificOutput?.updatedToolOutput).toBe('redacted');
  });

  it('a throwing handler is isolated and the rest still run', async () => {
    const { map, calls } = fakes((id) => {
      if (id === 'posttool/auto-lint') throw new Error('boom');
      return SILENT;
    });
    const r = await posttoolDispatch(input('Edit'), createTestContext(), map);
    expect(r.continue).toBe(true);
    expect(calls).toHaveLength(14);
  });
});

describe('flag variant (pre + post)', () => {
  const variant = unifiedToolHooks(shipped);

  it('keeps every PostToolUse group matcher, each with the one identical dispatcher command', () => {
    const groups = variant.hooks.PostToolUse;
    expect(groups.map((g: { matcher?: string }) => g.matcher)).toEqual(
      shipped.hooks.PostToolUse.map((g: { matcher?: string }) => g.matcher),
    );
    const commands = new Set(groups.map((g: { hooks: unknown[] }) => JSON.stringify(g.hooks)));
    expect(commands.size).toBe(1);
    expect([...commands][0]).toContain(UNIFIED_POSTTOOL_HANDLER);
  });

  it('drops PostToolBatch (tool-batch-observer) from the variant only', () => {
    expect(variant.hooks.PostToolBatch).toBeUndefined();
    expect(shipped.hooks.PostToolBatch).toBeDefined();
  });

  it('leaves every other event unchanged', () => {
    for (const event of Object.keys(shipped.hooks)) {
      if (['PreToolUse', 'PostToolUse', 'PostToolBatch'].includes(event)) continue;
      expect(variant.hooks[event]).toEqual(shipped.hooks[event]);
    }
  });

  it('default stays off: the shipped hooks.json does not reference the post dispatcher', () => {
    expect(JSON.stringify(shipped)).not.toContain(UNIFIED_POSTTOOL_HANDLER);
  });
});
